"""tessaro_feeds - Provides certificate pin store functionality."""

import hashlib
import os
import json


def fingerprint(cert_der: bytes) -> str:
    """Compute the SHA-256 fingerprint of a DER-encoded certificate."""
    return hashlib.sha256(cert_der).hexdigest()


class PinStore:
    """Stores and validates certificate pin fingerprints."""

    def __init__(self, pins: dict):
        self.pins = pins

    @classmethod
    def load(cls) -> "PinStore":
        """Load the pin store from the default configuration file."""
        config_path = os.environ.get(
            "TESSARO_PINS_PATH",
            os.path.join(os.path.dirname(__file__), "pins.json")
        )
        if os.path.exists(config_path):
            with open(config_path, "r") as f:
                pins = json.load(f)
        else:
            pins = {}
        return cls(pins)

    def matches(self, host: str, fp: str) -> bool:
        """Return True if the fingerprint matches the pinned value for the host."""
        expected = self.pins.get(host)
        if expected is None:
            return False
        return expected == fp
